package dev.gbppimentel.zzz;
import java.util.*;import org.json.*;
final class SessionCookies {
 static String parse(String input)throws Exception{if(input==null||input.length()>65536)throw new IllegalArgumentException();input=input.trim();LinkedHashMap<String,String> jar=new LinkedHashMap<>();if(input.startsWith("[")||input.startsWith("{")){Object parsed=new JSONTokener(input).nextValue();if(parsed instanceof JSONObject&&((JSONObject)parsed).optJSONArray("cookies")!=null)parsed=((JSONObject)parsed).getJSONArray("cookies");if(parsed instanceof JSONArray){JSONArray a=(JSONArray)parsed;for(int i=0;i<a.length();i++){JSONObject c=a.getJSONObject(i);String d=c.optString("domain","hoyolab.com");if(d.equals("hoyolab.com")||d.endsWith(".hoyolab.com"))add(jar,c.optString("name"),c.optString("value"));}}else if(parsed instanceof JSONObject){JSONObject o=(JSONObject)parsed;Iterator<String> keys=o.keys();while(keys.hasNext()){String k=keys.next();add(jar,k,o.optString(k));}}}else{if(input.toLowerCase(Locale.ROOT).startsWith("cookie:"))input=input.substring(7).trim();for(String part:input.split(";")){int k=part.indexOf('=');if(k>0)add(jar,part.substring(0,k).trim(),part.substring(k+1).trim());}}if(!(jar.containsKey("ltoken_v2")||jar.containsKey("ltoken")||jar.containsKey("cookie_token_v2")||jar.containsKey("cookie_token")))throw new IllegalArgumentException();StringBuilder out=new StringBuilder();for(Map.Entry<String,String> e:jar.entrySet())out.append(e.getKey()).append('=').append(e.getValue()).append("; ");return out.toString();}
 private static void add(Map<String,String> jar,String name,String value){if(!name.matches("(?:ltuid|ltoken|ltmid|account_id|account_mid|cookie_token|stuid|stoken)(?:_v2)?|e_nap_token|e_lrsag")||value.isEmpty()||value.indexOf('\r')>=0||value.indexOf('\n')>=0||value.indexOf(';')>=0)return;jar.put(name,value);}
}
